SELECT member_id, email, name, phone, role, status, bonus_points, total_orders, total_spent, created_at, updated_at FROM member
(name ILIKE '%' || #{keyword} || '%' OR email ILIKE '%' || #{keyword} || '%' OR phone ILIKE '%' || #{keyword} || '%')
AND status = #{status}
ORDER BY created_at DESC LIMIT #{pageSize} OFFSET #{offset}

SELECT COUNT(*) FROM member
(name ILIKE '%' || #{keyword} || '%' OR email ILIKE '%' || #{keyword} || '%' OR phone ILIKE '%' || #{keyword} || '%')
AND status = #{status}

mapper.update:
UPDATE member
SET status = #{status}, updated_at = CURRENT_TIMESTAMP
WHERE member_id = #{memberId}

UPDATE member
SET role = #{role}, updated_at = CURRENT_TIMESTAMP
WHERE member_id = #{memberId}
